Here is the commit message:
net: usb: rtl8150 fix unintiatilzed variables in
 rtl8150_get_link_ksettings

This functions retrieves values by passing a pointer. As the function
that retrieves them can fail before touching the pointers, the variables
must be initialized.

Fixes: 1da177e4c3f4 ("Linux-2.6.12-rc2")
Reported-by: syzbot+5186630949e3c55f0799@syzkaller.appspotmail.com
Signed-off-by: Oliver Neukum <oneukum@suse.com>
Link: https://lore.kernel.org/r/20240619132816.11526-1-oneukum@suse.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug arises from the use of uninitialized variables `lpa` and `bmcr` in the function `rtl8150_get_link_ksettings`. If the function that retrieves values for these variables fails before they are assigned, the variables would retain garbage values, leading to undefined behavior when they are subsequently used.

Here is the patch:

 static int rtl8150_get_link_ksettings(struct net_device *netdev,
 				      struct ethtool_link_ksettings *ecmd)
 {
 	rtl8150_t *dev = netdev_priv(netdev);
-	short lpa, bmcr;
+	short lpa = 0;
+	short bmcr = 0;
 	u32 supported;

 	supported = (SUPPORTED_10baseT_Half |
 			  SUPPORTED_10baseT_Full |
 			  SUPPORTED_100baseT_Half |
 			  SUPPORTED_100baseT_Full |
 			  SUPPORTED_Autoneg |
 			  SUPPORTED_TP | SUPPORTED_MII);
 	ecmd->base.port = PORT_TP;
 	ecmd->base.phy_address = dev->phy;
 	get_registers(dev, BMCR, 2, &bmcr);
 	get_registers(dev, ANLP, 2, &lpa);
 	if (bmcr & BMCR_ANENABLE) {
 		u32 speed = ((lpa & (LPA_100HALF | LPA_100FULL)) ?
 			     SPEED_100 : SPEED_10);
 		ecmd->base.speed = speed;
 		ecmd->base.autoneg = AUTONEG_ENABLE;
 		if (speed == SPEED_100)
 			ecmd->base.duplex = (lpa & LPA_100FULL) ?
 			    DUPLEX_FULL : DUPLEX_HALF;
 		else
 			ecmd->base.duplex = (lpa & LPA_10FULL) ?
 			    DUPLEX_FULL : DUPLEX_HALF;
 	} else {
 		ecmd->base.autoneg = AUTONEG_DISABLE;
 		ecmd->base.speed = ((bmcr & BMCR_SPEED100) ?
 					     SPEED_100 : SPEED_10);
 		ecmd->base.duplex = (bmcr & BMCR_FULLDPLX) ?
 		    DUPLEX_FULL : DUPLEX_HALF;
 	}

 	ethtool_convert_legacy_u32_to_link_mode(ecmd->link_modes.supported,
 						supported);

 	return 0;
 }



